<template><el-drawer :model-value="!!parcel" @close="$emit('close')" size="440px" :title="parcel?.address"><div v-if="parcel"><el-descriptions :column="1" border><el-descriptions-item v-for="[k,v] in fields" :key="k" :label="t(k)">{{ v ?? '—' }}</el-descriptions-item></el-descriptions><h3>{{ t('覆盖经纪人') }}</h3><p>{{ parcel.coveringAgents?.map(a=>a.name).join(', ') || '—' }}</p></div></el-drawer></template><script setup>import {computed} from 'vue';import {t} from '../i18n';const props=defineProps({parcel:Object});defineEmits(['close']);const fields=computed(()=>props.parcel ? [['区域',props.parcel.suburb],['地块',props.parcel.lotplan],['已登记',props.parcel.registered?t('是'):t('否')],['业主姓名',props.parcel.ownerNames],['上次成交价',props.parcel.lastSalePrice],['上次成交日期',props.parcel.lastSaleDate],['持有年数',props.parcel.yearsHeld],['异地业主',props.parcel.absenteeOwner?t('是'):t('否')]]:[])</script>
